import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { getC03GithubOidcToken } from "./c03-github-oidc-token.mjs";
import { fileURLToPath, pathToFileURL } from "node:url";

const SCRIPT_PATH = fileURLToPath(import.meta.url);
const REPO_ROOT = path.resolve(path.dirname(SCRIPT_PATH), "../..");
const ATTESTATION_RELATIVE_PATH = "supabase/functions/_shared/c03-runtime-attestation.ts";
const CONTRACT_RELATIVE_PATH = "supabase/functions/assessment-config-release/release-contract.json";
const SOURCE_ROOTS = [
  "supabase/functions/assessment-access",
  "supabase/functions/assessment-config-release",
];
const SOURCE_EXTENSIONS = new Set([".ts", ".mts", ".tsx", ".js", ".mjs", ".jsx", ".json", ".jsonc", ".toml", ".wasm"]);

async function collectSourceFiles(root, relativeDirectory) {
  const absoluteDirectory = path.join(root, relativeDirectory);
  const entries = await readdir(absoluteDirectory, { withFileTypes: true });
  const files = [];
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const relativePath = path.posix.join(relativeDirectory.replaceAll(path.sep, "/"), entry.name);
    if (entry.isDirectory()) {
      files.push(...await collectSourceFiles(root, relativePath));
    } else if (
      entry.isFile() &&
      SOURCE_EXTENSIONS.has(path.extname(entry.name)) &&
      relativePath !== ATTESTATION_RELATIVE_PATH
    ) {
      files.push(relativePath);
    }
  }
  return files;
}

export async function computeEdgeSourceDigest(root = REPO_ROOT) {
  const files = [];
  for (const sourceRoot of SOURCE_ROOTS) {
    files.push(...await collectSourceFiles(root, sourceRoot));
  }
  files.sort((a, b) => a.localeCompare(b));
  if (files.length === 0) throw new Error("C-03 source digest input set is empty.");
  const hash = createHash("sha256");
  for (const relativePath of files) {
    hash.update(relativePath, "utf8");
    hash.update("\0", "utf8");
    hash.update(await readFile(path.join(root, relativePath)));
    hash.update("\0", "utf8");
  }
  return hash.digest("hex");
}

export async function buildRuntimeAttestation({ root = REPO_ROOT, commitSha }) {
  const gitCommitSha = String(commitSha || "").trim().toLowerCase();
  if (!/^[0-9a-f]{40}([0-9a-f]{24})?$/.test(gitCommitSha)) {
    throw new Error("A full immutable Git commit SHA is required for C-03 attestation.");
  }
  const contract = JSON.parse(await readFile(path.join(root, CONTRACT_RELATIVE_PATH), "utf8"));
  if (contract.schemaVersion !== "C03_RUNTIME_ATTESTATION_V1") {
    throw new Error("Unsupported C-03 runtime attestation contract schema.");
  }
  for (const key of ["fixtureSetVersion", "migrationContractVersion"]) {
    if (typeof contract[key] !== "string" || contract[key].trim() === "") {
      throw new Error("Missing pinned release contract field: " + key);
    }
  }
  const sourceDigest = await computeEdgeSourceDigest(root);
  return Object.freeze({
    schemaVersion: contract.schemaVersion,
    gitCommitSha,
    edgeReleaseRef: "sha256:" + sourceDigest,
    fixtureSetVersion: contract.fixtureSetVersion,
    migrationContractVersion: contract.migrationContractVersion,
  });
}

export function renderRuntimeAttestation(attestation) {
  return [
    "// GENERATED by .github/scripts/c03-release-attestation.mjs; do not edit.",
    "// edgeReleaseRef is SHA-256 over the sorted Edge source manifest, excluding this file.",
    "export const C03_RUNTIME_ATTESTATION = Object.freeze(" + JSON.stringify(attestation, null, 2) + ");",
    "",
  ].join(String.fromCharCode(10));
}

function gitHead(root) {
  return execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" }).trim().toLowerCase();
}

export async function prepareAttestation({ root = REPO_ROOT, commitSha, outputPath } = {}) {
  const actualHead = gitHead(root);
  const requestedCommit = String(commitSha || actualHead).trim().toLowerCase();
  if (requestedCommit !== actualHead) {
    throw new Error("C-03 attestation commit must equal the checked-out HEAD: " + actualHead);
  }
  const attestation = await buildRuntimeAttestation({ root, commitSha: actualHead });
  const destination = outputPath || path.join(root, ATTESTATION_RELATIVE_PATH);
  await writeFile(destination, renderRuntimeAttestation(attestation), "utf8");
  return attestation;
}

export async function verifyDeployedAttestation({
  root = REPO_ROOT,
  commitSha,
  assessmentTypeId,
  baseUrl: suppliedBaseUrl,
  anonKey: suppliedAnonKey,
  oidcToken: suppliedOidcToken,
  fetchImpl = fetch,
} = {}) {
  const actualHead = gitHead(root);
  const requestedCommit = String(commitSha || actualHead).trim().toLowerCase();
  if (requestedCommit !== actualHead) {
    throw new Error("C-03 verification commit must equal the checked-out HEAD: " + actualHead);
  }
  const expected = await buildRuntimeAttestation({ root, commitSha: actualHead });
  const baseUrl = String(suppliedBaseUrl || process.env.SUPABASE_URL || "").replace(/\/$/, "");
  const anonKey = String(suppliedAnonKey || process.env.SUPABASE_ANON_KEY || "");
  const oidcToken = String(suppliedOidcToken || await getC03GithubOidcToken());
  const selectedAssessmentTypeId = String(assessmentTypeId || process.env.C03_ASSESSMENT_TYPE_ID || "").trim();
  if (!baseUrl || !anonKey || !oidcToken || !selectedAssessmentTypeId) {
    throw new Error("Read-only deployed attestation verification requires SUPABASE_URL, SUPABASE_ANON_KEY, GitHub Actions OIDC, and C03_ASSESSMENT_TYPE_ID.");
  }
  const response = await fetchImpl(baseUrl + "/functions/v1/assessment-config-release", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "apikey": anonKey,
      "Authorization": "Bearer " + oidcToken,
    },
    body: JSON.stringify({ action: "ci_export", assessment_type_id: selectedAssessmentTypeId }),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || payload?.success !== true) {
    throw new Error("Deployed C-03 attestation endpoint rejected the read-only export: HTTP " + response.status + " " + JSON.stringify(payload));
  }
  const actual = payload?.data?.runtimeMetadata;
  for (const key of ["schemaVersion", "gitCommitSha", "edgeReleaseRef", "fixtureSetVersion", "migrationContractVersion"]) {
    if (actual?.[key] !== expected[key]) {
      throw new Error("Deployed verifier attestation mismatch for " + key + ": expected " + expected[key] + ", got " + String(actual?.[key]));
    }
  }

  const scorerResponse = await fetchImpl(baseUrl + "/functions/v1/assessment-access", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "apikey": anonKey,
      "Authorization": "Bearer " + anonKey,
    },
    body: JSON.stringify({ action: "c03_runtime_attestation" }),
  });
  const scorerPayload = await scorerResponse.json().catch(() => ({}));
  if (!scorerResponse.ok || scorerPayload?.success !== true) {
    throw new Error("Deployed scorer attestation endpoint rejected the read-only check: HTTP " + scorerResponse.status + " " + JSON.stringify(scorerPayload));
  }
  const scorerActual = scorerPayload?.data?.runtimeMetadata;
  for (const key of ["schemaVersion", "gitCommitSha", "edgeReleaseRef", "fixtureSetVersion", "migrationContractVersion"]) {
    if (scorerActual?.[key] !== expected[key]) {
      throw new Error("Deployed scorer attestation mismatch for " + key + ": expected " + expected[key] + ", got " + String(scorerActual?.[key]));
    }
  }
  return { expected, verifier: actual, scorer: scorerActual, assessmentTypeId: selectedAssessmentTypeId };
}

async function main() {
  const [mode, ...args] = process.argv.slice(2);
  const outputIndex = args.indexOf("--output");
  const outputPath = outputIndex >= 0 ? path.resolve(process.cwd(), args[outputIndex + 1]) : undefined;
  if (mode === "prepare") {
    const attestation = await prepareAttestation({ commitSha: process.env.GITHUB_SHA || process.env.C03_GIT_COMMIT_SHA, outputPath });
    console.log(JSON.stringify(attestation, null, 2));
    return;
  }
  if (mode === "verify") {
    const result = await verifyDeployedAttestation({ commitSha: process.env.GITHUB_SHA || process.env.C03_GIT_COMMIT_SHA });
    console.log(JSON.stringify(result, null, 2));
    return;
  }
  throw new Error("Usage: node .github/scripts/c03-release-attestation.mjs <prepare|verify> [--output path]");
}

if (process.argv[1] && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  });
}
